<?php

declare(strict_types=1);

namespace Phil\ContentBundle\Infrastructure\Http;

use Override;
use Phil\ContentBundle\Application\Contract\CanonicalAddresses;
use Phil\ContentBundle\Domain\ValueObject\ContentReference;
use Phil\LocaleDimensions\Locale;
use Phil\Url\Exception\InvalidUrl;
use Phil\Url\Url;

/**
 * The absolute URL of a content's current route, generated by the router as `ContentUrlGenerator` generates it, and
 * read by `phil/url`. A URL that is not a public web address — `http://localhost/…`, a console without
 * `framework.router.default_uri` — has no canonical form: it gives `null`, unless `$allowLocalhost` (the kernel's
 * debug mode) accepts `localhost` for development and tests.
 */
final readonly class ContentCanonicalAddresses implements CanonicalAddresses
{
    public function __construct(
        private ContentUrlGenerator $urls,
        private bool $allowLocalhost = false,
    ) {
    }

    #[Override]
    public function of(ContentReference $content, Locale $locale): ?Url
    {
        $url = $this->urls->generate($content, $locale, absolute: true);

        if (null === $url) {
            return null;
        }

        try {
            return Url::fromString($url, $this->allowLocalhost);
        } catch (InvalidUrl) {
            return null;
        }
    }
}
